INSERT INTO help_organizations (name, slug, legal_name, registration_number, type, status, short_description, description, public_email, public_phone, website_url, facebook_url, instagram_url, address, city, district, region, country_code, image_url, image_key, directory_profile_id, import_key, source_url, source_data_json, seo_json, published_at, last_verified_at, archived_at, created_at, updated_at, created_by, updated_by)
SELECT source.name, source.slug, source.legal_name, source.registration_number, source.type, source.status, source.short_description, source.description, source.public_email, source.public_phone, source.website_url, source.facebook_url, source.instagram_url, source.address, source.city, source.district, source.region, source.country_code, source.image_url, source.image_key, source.directory_profile_id, source.import_key, source.source_url, source.source_data_json, source.seo_json, source.published_at, source.last_verified_at, source.archived_at, source.created_at, source.updated_at, source.created_by, source.updated_by
FROM source
WHERE NOT EXISTS (
  SELECT 1
  FROM help_organizations existing
  WHERE existing.import_key = source.import_key
    AND existing.slug = source.slug
    AND existing.name = source.name
);

